content:
That error on Vercel usually means connection exhaustion: every serverless invocation opens new Prisma connections. Two fixes:

1. Use Neon's **pooled** connection string (the `-pooler` host) for `DATABASE_URL`.
2. Reuse a single PrismaClient across hot invocations:

```ts
// lib/db.ts
import { PrismaClient } from '@prisma/client';
const g = globalThis as unknown as { prisma?: PrismaClient };
export const prisma = g.prisma ?? new PrismaClient();
if (process.env.NODE_ENV !== 'production') g.prisma = prisma;
```

Also set `connection_limit=1` on the pooled URL.

Here's an invoice document component:

```tsx
// components/InvoicePdf.tsx
import { Document, Page, Text, View, Font, StyleSheet } from '@react-pdf/renderer';

Font.register({ family: 'Inter', src: '/fonts/Inter-Regular.ttf' });

const s = StyleSheet.create({ page: { fontFamily: 'Inter', padding: 32 }, row: { flexDirection: 'row', justifyContent: 'space-between' } });

export function InvoicePdf({ items }: { items: { name: string; amount: number }[] }) {
  const subtotal = items.reduce((a, i) => a + i.amount, 0);
  const gst = Math.round(subtotal * 0.18 * 100) / 100;
  return (
    <Document><Page style={s.page}>
      {items.map((i) => (<View key={i.name} style={s.row}><Text>{i.name}</Text><Text>₹{i.amount.toFixed(2)}</Text></View>))}
      <View style={s.row}><Text>GST (18%)</Text><Text>₹{gst.toFixed(2)}</Text></View>
      <View style={s.row}><Text>Total</Text><Text>₹{(subtotal + gst).toFixed(2)}</Text></View>
    </Page></Document>
  );
}
```

The ₹ glyph renders because Inter includes it — the default Helvetica does not.
